import re
from typing import List, Tuple, Union

# Token type: (type, value)
Token = Tuple[str, Union[str, float]]

def tokenize(expression: str) -> List[Token]:
    """Convert an arithmetic expression string into a list of tokens."""
    if not expression.strip():
        raise ValueError("Empty expression")
    if re.search(r'[^\d.+\-*/()eE \t\n\r]', expression):
        raise ValueError("Invalid character in expression")

    # Patterns for numbers (int/float/scientific) and operators
    number_re = r'\d+(?:\.\d*)?(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?'
    op_re = r'\*\*|[+\-*/()]'
    combined_re = re.compile(f'({number_re})|({op_re})')

    tokens: List[Token] = []
    for m in combined_re.finditer(expression):
        if m.group(1):
            tokens.append(('NUMBER', float(m.group(1))))
        else:
            op = m.group(2)
            if op == '**':
                tokens.append(('POW', '**'))
            elif op in '+-*/':
                tokens.append(('OP', op))
            elif op == '(':
                tokens.append(('LPAREN', '('))
            else:
                tokens.append(('RPAREN', ')'))
    tokens.append(('EOF', None))
    return tokens


class Parser:
    """Recursive-descent parser that evaluates arithmetic expressions on the fly."""

    def __init__(self, tokens: List[Token]) -> None:
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token:
        return self.tokens[self.pos]

    def consume(self) -> Token:
        token = self.tokens[self.pos]
        self.pos += 1
        return token

    def expect(self, token_type: str) -> Token:
        token = self.current_token()
        if token[0] != token_type:
            raise ValueError(f"Expected '{token_type}', got '{token[0]}'")
        return self.consume()

    def parse(self) -> float:
        result = self.parse_expression()
        if self.current_token()[0] != 'EOF':
            raise ValueError(f"Unexpected token after expression: {self.current_token()}")
        return result

    # Grammar (lowest to highest precedence):
    # expression -> term (('+' | '-') term)*
    # term       -> factor (('*' | '/') factor)*
    # factor     -> '-' factor | power
    # power      -> primary ('**' factor)*   # Right-associative
    # primary    -> NUMBER | '(' expression ')'

    def parse_expression(self) -> float:
        left = self.parse_term()
        while self.current_token()[0] == 'OP' and self.current_token()[1] in '+-':
            op = self.consume()[1]
            right = self.parse_term()
            left = left + right if op == '+' else left - right
        return left

    def parse_term(self) -> float:
        left = self.parse_factor()
        while self.current_token()[0] == 'OP' and self.current_token()[1] in '*/':
            op = self.consume()[1]
            right = self.parse_factor()
            if op == '*':
                left *= right
            else:
                if right == 0.0:
                    raise ValueError("Division by zero")
                left /= right
        return left

    def parse_factor(self) -> float:
        if self.current_token()[0] == 'OP' and self.current_token()[1] == '-':
            self.consume()
            return -self.parse_factor()
        return self.parse_power()

    def parse_power(self) -> float:
        base = self.parse_primary()
        if self.current_token()[0] == 'POW':
            self.consume()
            exponent = self.parse_factor()  # Recursive call ensures right-associativity
            return base ** exponent
        return base

    def parse_primary(self) -> float:
        token = self.current_token()
        if token[0] == 'NUMBER':
            self.consume()
            return token[1]
        elif token[0] == 'LPAREN':
            self.consume()
            result = self.parse_expression()
            self.expect('RPAREN')
            return result
        elif token[0] == 'EOF':
            raise ValueError("Unexpected end of input")
        else:
            raise ValueError(f"Unexpected token: {token}")


def evaluate(expression: str) -> float:
    """Public API: Parse and evaluate an arithmetic expression string."""
    tokens = tokenize(expression)
    parser = Parser(tokens)
    return parser.parse()


if __name__ == "__main__":
