    # 3 + 4 * 2 ** 2  ->  3 + 4 * 4  ->  3 + 16  ->  19.0
    print(f"3 + 4 * 2 ** 2 = {evaluate('3 + 4 * 2 ** 2')}")

    # Example 2: Parentheses
    # (1 + 2) * (3 - 4)  ->  3 * -1  ->  -3.0
    print(f"(1 + 2) * (3 - 4) = {evaluate('(1 + 2) * (3 - 4)')}")

    # Example 3: Unary minus (demonstrates ** binds tighter than unary -)
