    print(f"-5 ** 2 + 3 = {evaluate('-5 ** 2 + 3')}")

    # Example 4: Right-associativity of **
    # 2 ** 3 ** 2  ->  2 ** (3 ** 2)  ->  2 ** 9  ->  512.0
    print(f"2 ** 3 ** 2 = {evaluate('2 ** 3 ** 2')}")

