            raise ExpressionError(f"Expected {token_type} '{token_value}' but got {token}")
        return self.advance()

    def parse(self) -> float:
        result = self.parse_expr()
        if self.pos < len(self.tokens):
            raise ExpressionError(f"Unexpected token after expression: {self.tokens[self.pos]}")
        return result

    def parse_expr(self) -> float:
        """Handles + and - (lowest precedence, left-associative)."""
        left = self.parse_term()
