from typing import List, Dict, Any, Callable, TypeVar, Optional

T = TypeVar('T', bound='Table')

class Table:
    """In-memory SQL-like table supporting a composable fluent API."""

    def __init__(self, rows: List[Dict[str, Any]], name: str = "") -> None:
        self.rows = rows
        self.name = name

    def select(self: T, *columns: str) -> T:
        """Project specific columns from each row."""
        new_rows = [
            {k: row[k] for k in columns if k in row}
            for row in self.rows
        ]
        return self.__class__(new_rows, self.name)

    def where(self: T, predicate: Callable[[Dict[str, Any]], bool]) -> T:
        """Filter rows based on a boolean predicate."""
        new_rows = [row for row in self.rows if predicate(row)]
        return self.__class__(new_rows, self.name)

    def join(self: T, other: 'Table', on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> T:
        """Inner join with another table using a predicate."""
        new_rows = []
        for l_row in self.rows:
            for r_row in other.rows:
                if on(l_row, r_row):
                    prefix_l = f"{self.name}." if self.name else ""
                    prefix_r = f"{other.name}." if other.name else ""
                    merged = {
                        f"{prefix_l}{k}": v for k, v in l_row.items()
                    }
                    merged.update({
                        f"{prefix_r}{k}": v for k, v in r_row.items()
                    })
                    new_rows.append(merged)
        return self.__class__(new_rows, f"{self.name}_{other.name}" if self.name or other.name else "")

    def group_by(self: T, column: str) -> T:
        """Group rows by a column. Keeps the first row encountered per unique group.
        Note: Full SQL-like grouping with aggregates (SUM, COUNT, etc.) would require 
        additional aggregation methods."""
        seen = set()
        new_rows = []
        for row in self.rows:
            key = row.get(column)
            if key not in seen:
                seen.add(key)
                new_rows.append(row)
        return self.__class__(new_rows, self.name)

    def order_by(self: T, column: str, descending: bool = False) -> T:
        """Sort rows by a column."""
        def safe_key(row: Dict[str, Any]) -> Any:
            val = row.get(column)
            # Sort None values to the end, handle mixed types gracefully
            if val is None:
                return (1, "")
            try:
                return (0, val)
            except TypeError:
                return (0, str(val))

        new_rows = sorted(self.rows, key=safe_key, reverse=descending)
        return self.__class__(new_rows, self.name)

    def limit(self: T, n: int) -> T:
        """Limit the result to the first n rows."""
        return self.__class__(self.rows[:n], self.name)

    def __repr__(self) -> str:
        return f"Table(name={self.name!r}, rows={self.rows})"

