from __future__ import annotations
from typing import List, Dict, Any, Callable

class Table:
    """A small in-memory SQL-like query engine with a composable fluent API."""

    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        self.rows = rows

    def select(self, *columns: str) -> Table:
        """Project only the specified columns."""
        return Table([{k: row[k] for k in columns if k in row} for row in self.rows])

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Table:
        """Filter rows based on a boolean predicate function."""
        return Table([row for row in self.rows if predicate(row)])

    def join(self, other: Table, on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> Table:
        """Inner join with another table using a predicate."""
        joined = []
        for l in self.rows:
            for r in other.rows:
                if on(l, r):
                    merged = {**l, **r}
                    # Resolve column name collisions by prefixing right-side keys
                    for k in r:
                        if k in l:
                            merged[f"_r_{k}"] = r[k]
                            del merged[k]
                    joined.append(merged)
        return Table(joined)

    def group_by(self, column: str) -> Table:
        """Group rows by a column, retaining the first row per group.
        Note: Full SQL aggregation (SUM, COUNT, etc.) is not implemented in this minimal engine."""
        seen = {}
        new_rows = []
        for row in self.rows:
            key = row.get(column)
            if key not in seen:
                seen[key] = True
                new_rows.append({k: v for k, v in row.items()})
        return Table(new_rows)

    def order_by(self, column: str, descending: bool = False) -> Table:
        """Sort rows by a column. Assumes consistent types within the column."""
        return Table(
            sorted(self.rows, key=lambda r: r.get(column), reverse=descending)
        )

    def limit(self, n: int) -> Table:
        """Limit the result set to n rows."""
        return Table(self.rows[:n])

    def __repr__(self) -> str:
        return f"Table(rows={self.rows})"

