import re
from typing import List, Union

class Token:
    """Represents a lexical token."""
    def __init__(self, type: str, value: Union[str, float]):
        self.type = type
        self.value = value

    def __repr__(self) -> str:
        return f"Token({self.type}, {self.value!r})"

class LexerError(Exception):
    """Raised when the input contains invalid characters or formatting."""
    pass

class ParserError(Exception):
    """Raised when the token stream violates the arithmetic grammar."""
    pass

class Lexer:
    """Tokenizes an arithmetic expression string."""
    def __init__(self, text: str):
        self.text = text
        self.tokens: List[Token] = []
        self._tokenize()

    def _tokenize(self) -> None:
        # Matches: whitespace, numbers (int/float), or operators/parens
        pattern = re.compile(r'\s+|(\d+\.\d*|\.\d+|\d+)|([+\-*/()])')
        last_end = 0
        for match in pattern.finditer(self.text):
            if match.start() > last_end:
                raise LexerError(f"Invalid character '{self.text[last_end:match.start()]}'")
            last_end = match.end()
            if match.group(1):
                self.tokens.append(Token('NUMBER', float(match.group(1))))
            elif match.group(2):
                self.tokens.append(Token(match.group(2), match.group(2)))
        if last_end < len(self.text):
            raise LexerError(f"Invalid character '{self.text[last_end:]}'")
        self.tokens.append(Token('EOF', None))

class Parser:
    """Recursive-descent parser for arithmetic expressions.

    Grammar (low to high precedence):
      expr     -> unary (('+' | '-') unary)*
      term     -> power (('*' | '/') power)*
      power    -> unary ('**' unary)*   # Right-associative
      unary    -> ('+' | '-') unary | primary
      primary  -> NUMBER | '(' expr ')'
    """
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def _current(self) -> Token:
        return self.tokens[self.pos]

    def _eat(self, token_type: str) -> Token:
        if self._current().type == token_type:
            token = self._current()
            self.pos += 1
            return token
        raise ParserError(f"Expected {token_type}, got {self._current()}")

    def parse(self) -> float:
        result = self.expr()
        if self._current().type != 'EOF':
            raise ParserError(f"Unexpected token: {self._current()}")
        return result

    def expr(self) -> float:
        result = self.unary()
        while self._current().type in ('+', '-'):
            op = self._eat(self._current().type).value
            right = self.unary()
            result = result + right if op == '+' else result - right
        return result

    def term(self) -> float:
        result = self.power()
        while self._current().type in ('*', '/'):
            op = self._eat(self._current().type).value
            right = self.power()
            if op == '*':
                result *= right
            else:
                if right == 0:
                    raise ParserError("Division by zero")
                result /= right
        return result

    def power(self) -> float:
        base = self.unary()
        if self._current().type == '**':
            self._eat('**')
            exponent = self.unary()
            return base ** exponent
        return base

    def unary(self) -> float:
        if self._current().type in ('+', '-'):
            op = self._eat(self._current().type).value
            return -self.unary() if op == '-' else self.unary()
        return self.primary()

    def primary(self) -> float:
        token = self._current()
        if token.type == 'NUMBER':
            self._eat('NUMBER')
            return token.value
        elif token.type == '(':
            self._eat('(')
            result = self.expr()
            self._eat(')')
            return result
        else:
            raise ParserError(f"Unexpected token in primary: {token}")

def evaluate(expression: str) -> float:
    """Evaluate an arithmetic expression string and return the result as a float.

    Supports: integers, floats, +, -, *, /, **, unary minus, parentheses.
    Precedence: ** > unary > * / > + -
    """
    try:
        lexer = Lexer(expression)
        parser = Parser(lexer.tokens)
        return parser.parse()
    except (LexerError, ParserError) as e:
        raise ValueError(f"Invalid expression: {e}") from e

# -----------------------------------------------------------------------------
# Usage Examples
# -----------------------------------------------------------------------------
if __name__ == "__main__":
    # 1. Operator Precedence: * binds tighter than +
    print(f"2 + 3 * 4      = {evaluate('2 + 3 * 4')}")       # 14.0

    # 2. Parentheses Override Precedence
    print(f"(2 + 3) * 4    = {evaluate('(2 + 3) * 4')}")     # 20.0

    # 3. Unary Minus & Exponentiation Precedence: ** > unary minus
    print(f"-3 ** 2        = {evaluate('-3 ** 2')}")         # -9.0
    print(f"(-3) ** 2      = {evaluate('(-3) ** 2')}")       # 9.0

    # 4. Right-Associativity of **
    print(f"2 ** 3 ** 2    = {evaluate('2 ** 3 ** 2')}")     # 512.0

    # 5. Error Handling
    try:
        evaluate("2 + * 3")
    except ValueError as e:
        print(f"Caught expected error: {e}")

from __future__ import annotations

from typing import List, Tuple, Union

# Type alias for tokens: (type, value)
Token = Tuple[str, Union[str, float]]


class _Tokenizer:
    """Converts an expression string into a stream of typed tokens."""

    def __init__(self, text: str) -> None:
        self.text = text
        self.tokens: List[Token] = []
        self._tokenize()

    def _tokenize(self) -> None:
        i = 0
        n = len(self.text)
        while i < n:
            if self.text[i].isspace():
                i += 1
                continue

            # Numbers (integers or floats, including leading/trailing dots)
            if self.text[i].isdigit() or self.text[i] == '.':
                j = i
                dot_count = 0
                while j < n and (self.text[j].isdigit() or self.text[j] == '.'):
                    if self.text[j] == '.':
                        dot_count += 1
                    j += 1
                if dot_count > 1:
                    raise SyntaxError(f"Invalid number format at position {i}")
                self.tokens.append(('NUMBER', float(self.text[i:j])))
                i = j

            # Exponentiation operator (must be checked before single '*')
            elif self.text[i:i+2] == '**':
                self.tokens.append(('POW', '**'))
                i += 2

            # Single-character operators and parentheses
            elif self.text[i] in '+-*/()':
                self.tokens.append((self.text[i], self.text[i]))
                i += 1

            else:
                raise SyntaxError(f"Unexpected character '{self.text[i]}' at position {i}")

        self.tokens.append(('EOF', i))


class _Parser:
    """Recursive-descent parser enforcing: ** > unary +/- > * / > + -"""

    def __init__(self, tokens: List[Token]) -> None:
        self.tokens = tokens
        self.pos = 0

    def _current(self) -> Token:
        return self.tokens[self.pos]

    def _consume(self) -> Token:
        token = self.tokens[self.pos]
        self.pos += 1
        return token

    def parse(self) -> float:
        result = self.expr()
        if self._current()[0] != 'EOF':
            raise SyntaxError(f"Unexpected token '{self._current()[0]}' at position {self._current()[1]}")
        return result

    # expr     -> term (('+' | '-') term)*
    def expr(self) -> float:
        left = self.term()
        while self._current()[0] in ('+', '-'):
            op = self._consume()[0]
            right = self.term()
            left = left + right if op == '+' else left - right
        return left

    # term     -> factor (('*' | '/') factor)*
    def term(self) -> float:
        left = self.factor()
        while self._current()[0] in ('*', '/'):
            op = self._consume()[0]
            right = self.factor()
            if op == '*':
                left = left * right
            else:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                left = left / right
        return left

    # factor   -> unary ('**' factor)?   # Right-associative
    def factor(self) -> float:
        left = self.unary()
        if self._current()[0] == '**':
            self._consume()
            right = self.factor()  # Recursive call on right ensures right-associativity
            return left ** right
        return left

    # unary    -> ('+' | '-') factor | atom
    def unary(self) -> float:
        if self._current()[0] in ('+', '-'):
            op = self._consume()[0]
            val = self.factor()
            return -val if op == '-' else val
        return self.atom()

    # atom     -> NUMBER | '(' expr ')'
    def atom(self) -> float:
        token = self._current()
        if token[0] == 'NUMBER':
            self._consume()
            return token[1]
        elif token[0] == '(':
            self._consume()
            val = self.expr()
            self.expect(')')
            return val
        else:
            raise SyntaxError(f"Unexpected token '{token[0]}' at position {token[1]}")

    def expect(self, type_: str) -> Token:
        token = self._current()
        if token[0] != type_:
            raise SyntaxError(f"Expected '{type_}' but got '{token[0]}' at position {token[1]}")
        return self._consume()


def evaluate(expression: str) -> float:
    """
    Evaluates a mathematical expression string.

    Supports: integers/floats, +, -, *, /, **, unary +/-, parentheses.
    Precedence: ** > unary +/- > * / > + -

    Args:
        expression: A string containing the arithmetic expression.

    Returns:
        The evaluated float result.

    Raises:
        SyntaxError: On malformed input, unexpected tokens, or invalid numbers.
        ZeroDivisionError: On division by zero.
    """
    tokens = _Tokenizer(expression).tokens
    return _Parser(tokens).parse()


if __name__ == "__main__":
    # Example 1: Operator precedence (* before +)
    print(evaluate("2 + 3 * 4"))                # 14.0

    # Example 2: Right-associative exponentiation
    print(evaluate("2 ** 3 ** 2"))              # 512.0  (evaluates as 2 ** (3 ** 2))

    # Example 3: Unary minus, precedence, and parentheses
    print(evaluate("-2 ** 2 + (3 * 4)"))        # 8.0    (evaluates as -(2**2) + 12)

from __future__ import annotations
from typing import Any, Callable, TypeVar

T = TypeVar("T", bound="Table")


class Table:
    """In-memory SQL-like query engine with a composable fluent API."""

    def __init__(self, rows: list[dict[str, Any]] | None = None) -> None:
        self.rows: list[dict[str, Any]] = list(rows) if rows is not None else []

    def _new(self: T) -> T:
        """Return a fresh instance with a shallow copy of the current rows."""
        return self.__class__(list(self.rows))

    def select(self: T, *columns: str) -> T:
        """Project only the specified columns. Missing columns are silently skipped."""
        if not columns:
            return self._new()
        return self.__class__([
            {col: row[col] for col in columns if col in row}
            for row in self.rows
        ])

    def where(self: T, predicate: Callable[[dict[str, Any]], bool]) -> T:
        """Filter rows using a callable that receives each row dict and returns bool."""
        return self.__class__([row for row in self.rows if predicate(row)])

    def join(self: T, other: Table, on: Callable[[dict[str, Any], dict[str, Any]], bool]) -> T:
        """Inner join with the given table. Colliding keys from the right table get a '_right' suffix."""
        new_rows = []
        for l_row in self.rows:
            for r_row in other.rows:
                if on(l_row, r_row):
                    combined = {**l_row}
                    for k, v in r_row.items():
                        if k in combined:
                            combined[f"{k}_right"] = v
                        else:
                            combined[k] = v
                    new_rows.append(combined)
        return self.__class__(new_rows)

    def group_by(self: T, column: str) -> T:
        """Group rows by a column. Returns a Table where each row contains the group key and '_rows' list."""
        groups: dict[Any, list[dict[str, Any]]] = {}
        for row in self.rows:
            key = row.get(column)
            groups.setdefault(key, []).append(row)
        return self.__class__([
            {column: k, "_rows": v} for k, v in groups.items()
        ])

    def order_by(self: T, column: str, descending: bool = False) -> T:
        """Sort rows by a column. None/missing values are placed at the end."""
        def sort_key(row: dict[str, Any]) -> tuple[int, Any]:
            val = row.get(column)
            return (1, "") if val is None else (0, val)
        return self.__class__(sorted(self.rows, key=sort_key, reverse=descending))

    def limit(self: T, n: int) -> T:
        """Return at most the first n rows."""
        return self.__class__(self.rows[:n])

    def __repr__(self) -> str:
        return f"Table(rows={self.rows})"

# --- file boundary ---

# 1. Basic filtering, projection, ordering, and limiting
users = Table([
    {"id": 1, "name": "Alice", "age": 30, "dept": "Engineering"},
    {"id": 2, "name": "Bob", "age": 25, "dept": "Marketing"},
    {"id": 3, "name": "Charlie", "age": 35, "dept": "Engineering"},
    {"id": 4, "name": "Diana", "age": 28, "dept": "Marketing"},
])

result = (
    users
    .where(lambda r: r["age"] > 26)
    .select("name", "dept")
    .order_by("dept")
    .limit(2)
)
print(result.rows)
# [{'name': 'Charlie', 'dept': 'Engineering'}, {'name': 'Alice', 'dept': 'Engineering'}]


# 2. Inner join with key collision handling
orders = Table([
    {"order_id": 101, "user_id": 1, "amount": 150.0},
    {"order_id": 102, "user_id": 2, "amount": 75.5},
    {"order_id": 103, "user_id": 1, "amount": 200.0},
])

joined = (
    users
    .join(orders, on=lambda u, o: u["id"] == o["user_id"])
    .select("name", "order_id", "amount")
    .order_by("amount", descending=True)
)
print(joined.rows)
# [{'name': 'Alice', 'order_id': 103, 'amount': 200.0},
#  {'name': 'Alice', 'order_id': 101, 'amount': 150.0},
#  {'name': 'Bob', 'order_id': 102, 'amount': 75.5}]


# 3. Grouping (returns structured groups for downstream aggregation)
grouped = users.group_by("dept")
for group_row in grouped.rows:
    print(f"Dept: {group_row['dept']}, Members: {len(group_row['_rows'])}")
# Dept: Engineering, Members: 2
# Dept: Marketing, Members: 2

import re
from typing import List, Tuple

# ---------- Token types ----------
class TokenType:
    NUMBER = "NUMBER"
    PLUS = "PLUS"
    MINUS = "MINUS"
    MULT = "MULT"
    DIV = "DIV"
    EXPONENT = "EXPONENT"
    LPAREN = "LPAREN"
    RPAREN = "RPAREN"
    EOF = "EOF"


class Token:
    def __init__(self, type_: str, value: str, pos: int):
        self.type = type_
        self.value = value
        self.pos = pos

    def __repr__(self):
        return f"Token({self.type}, {self.value!r}, pos={self.pos})"


# ---------- Lexer ----------
class LexerError(Exception):
    pass


class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.tokens: List[Token] = []
        self._tokenise()

    def _tokenise(self):
        """Convert the input string into a list of tokens."""
        i = 0
        n = len(self.text)
        while i < n:
            ch = self.text[i]
            # skip whitespace
            if ch in " \t\n\r":
                i += 1
                continue

            # numbers (integer or float)
            if ch.isdigit() or ch == '.':
                start = i
                while i < n and (self.text[i].isdigit() or self.text[i] == '.'):
                    i += 1
                num_str = self.text[start:i]
                # allow at most one decimal point
                if num_str.count('.') > 1:
                    raise LexerError(f"Invalid number at position {start}: multiple decimal points")
                if num_str == '.':
                    raise LexerError(f"Invalid number at position {start}: single decimal point")
                self.tokens.append(Token(TokenType.NUMBER, num_str, start))
                continue

            # operators and parentheses
            if ch == '+':
                self.tokens.append(Token(TokenType.PLUS, '+', i))
                i += 1
            elif ch == '-':
                self.tokens.append(Token(TokenType.MINUS, '-', i))
                i += 1
            elif ch == '*':
                # check for **
                if i + 1 < n and self.text[i+1] == '*':
                    self.tokens.append(Token(TokenType.EXPONENT, '**', i))
                    i += 2
                else:
                    self.tokens.append(Token(TokenType.MULT, '*', i))
                    i += 1
            elif ch == '/':
                self.tokens.append(Token(TokenType.DIV, '/', i))
                i += 1
            elif ch == '(':
                self.tokens.append(Token(TokenType.LPAREN, '(', i))
                i += 1
            elif ch == ')':
                self.tokens.append(Token(TokenType.RPAREN, ')', i))
                i += 1
            else:
                raise LexerError(f"Invalid character {ch!r} at position {i}")

        self.tokens.append(Token(TokenType.EOF, '', n))

    def get_tokens(self) -> List[Token]:
        return self.tokens


# ---------- Parser ----------
class ParseError(Exception):
    pass


class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def _current(self) -> Token:
        return self.tokens[self.pos]

    def _consume(self, expected_type: str) -> Token:
        token = self._current()
        if token.type != expected_type:
            raise ParseError(
                f"Expected {expected_type} but got {token.type!r} at position {token.pos}"
            )
        self.pos += 1
        return token

    def _peek(self) -> Token:
        return self._current()

    # ---------- Grammar rules ----------
    # expression : term (('+'|'-') term)*
    # term       : factor (('*'|'/') factor)*
    # factor     : ('+'|'-')* power   (unary)
    # power      : atom ('**' factor)*   (right‑associative)
    # atom       : NUMBER | '(' expression ')'

    def parse_expression(self) -> float:
        result = self.parse_term()
        while self._peek().type in (TokenType.PLUS, TokenType.MINUS):
            token = self._peek()
            if token.type == TokenType.PLUS:
                self._consume(TokenType.PLUS)
                right = self.parse_term()
                result += right
            elif token.type == TokenType.MINUS:
                self._consume(TokenType.MINUS)
                right = self.parse_term()
                result -= right
        return result

    def parse_term(self) -> float:
        result = self.parse_factor()
        while self._peek().type in (TokenType.MULT, TokenType.DIV):
            token = self._peek()
            if token.type == TokenType.MULT:
                self._consume(TokenType.MULT)
                right = self.parse_factor()
                result *= right
            elif token.type == TokenType.DIV:
                self._consume(TokenType.DIV)
                right = self.parse_factor()
                if right == 0:
                    raise ParseError(f"Division by zero at position {token.pos}")
                result /= right
        return result

    def parse_factor(self) -> float:
        # handle unary plus and minus
        unary = 1.0
        while self._peek().type in (TokenType.PLUS, TokenType.MINUS):
            token = self._peek()
            if token.type == TokenType.MINUS:
                unary *= -1.0
            # plus does nothing
            self._consume(token.type)
        return unary * self.parse_power()

    def parse_power(self) -> float:
        base = self.parse_atom()
        # right‑associative: if we see '**', parse the right‑hand side as a factor
        if self._peek().type == TokenType.EXPONENT:
            self._consume(TokenType.EXPONENT)
            exponent = self.parse_factor()   # right side is a factor (includes unary)
            base = base ** exponent
        return base

    def parse_atom(self) -> float:
        token = self._peek()
        if token.type == TokenType.NUMBER:
            self._consume(TokenType.NUMBER)
            return float(token.value)
        if token.type == TokenType.LPAREN:
            self._consume(TokenType.LPAREN)
            expr = self.parse_expression()
            self._consume(TokenType.RPAREN)
            return expr
        raise ParseError(
            f"Unexpected token {token.type!r} at position {token.pos} "
            f"(expected a number or '(')"
        )

    def parse(self) -> float:
        result = self.parse_expression()
        # after full expression, we must be at EOF
        if self._peek().type != TokenType.EOF:
            raise ParseError(
                f"Extra token {self._peek().type!r} at position {self._peek().pos}"
            )
        return result


# ---------- Public API ----------
def evaluate(expression: str) -> float:
    """Parse and evaluate an arithmetic expression.

    Supports integers and floats, operators + - * / ** (right‑associative),
    unary minus, parentheses, and correct precedence (** > unary > * / > + -).

    Raises descriptive exceptions for malformed input.
    """
    if not expression.strip():
        raise ValueError("Empty expression")
    try:
        lexer = Lexer(expression)
        parser = Parser(lexer.get_tokens())
        return parser.parse()
    except (LexerError, ParseError) as e:
        # Re‑raise with a clear message
        raise ValueError(str(e)) from e


# ---------- Usage examples ----------
if __name__ == "__main__":
    # Example 1: precedence of * over +
    print(evaluate("3 + 5 * 2"))          # 13.0

    # Example 2: parentheses override precedence
    print(evaluate("(2 + 3) * 4"))        # 20.0

    # Example 3: unary minus and exponentiation (unary lower than **)
    print(evaluate("-2**3"))              # -8.0  ( = -(2**3) )

    # Example 4: right‑associativity of **
    print(evaluate("2**3**2"))            # 512.0 ( = 2**(3**2) )

    # Example 5: unary minus mixed with +
    print(evaluate("1 + -2"))             # -1.0  ( = 1 + (-2) )

    # Example 6: nested parentheses and unary
    print(evaluate("-(3 + 4 * (2 - 1))")) # -7.0

from typing import Any, Callable, Dict, List, Optional, Sequence, Union
import copy

class Table:
    """An in-memory table holding a list of rows as dictionaries."""

    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        # Deep copy to avoid unintended mutations
        self._rows = copy.deepcopy(rows)

    # ------------------------------------------------------------------
    # Public query methods (fluent API)
    # ------------------------------------------------------------------

    def select(self, *columns: str) -> 'Table':
        """
        Return a new Table with only the specified columns.
        If no columns are given, all columns are kept.
        """
        if not columns:
            return Table(self._rows)
        new_rows = []
        for row in self._rows:
            new_row = {col: row[col] for col in columns if col in row}
            new_rows.append(new_row)
        return Table(new_rows)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> 'Table':
        """
        Return a new Table containing only rows that satisfy the predicate.
        """
        new_rows = [row for row in self._rows if predicate(row)]
        return Table(new_rows)

    def join(
        self,
        other: 'Table',
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool]
    ) -> 'Table':
        """
        Perform an inner join with another Table.
        The `on` function takes a left row and a right row and returns True
        if they should be combined. Duplicate column names are overwritten
        by the right table's values.
        """
        new_rows = []
        for left_row in self._rows:
            for right_row in other._rows:
                if on(left_row, right_row):
                    merged = {**left_row, **right_row}  # right overwrites left
                    new_rows.append(merged)
        return Table(new_rows)

    def group_by(self, column: str) -> 'Table':
        """
        Group rows by the given column.
        Returns a new Table where each row has two keys:
          - the original column name (the group key value)
          - 'rows' (a list of all rows belonging to that group)
        """
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self._rows:
            key = row[column]
            if key not in groups:
                groups[key] = []
            groups[key].append(row)
        new_rows = [
            {column: key, 'rows': rows}
            for key, rows in groups.items()
        ]
        return Table(new_rows)

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        """
        Return a new Table sorted by the given column.
        """
        sorted_rows = sorted(
            self._rows,
            key=lambda row: row.get(column),
            reverse=descending
        )
        return Table(sorted_rows)

    def limit(self, n: int) -> 'Table':
        """
        Return a new Table containing at most the first n rows.
        """
        return Table(self._rows[:n])

    # ------------------------------------------------------------------
    # Utility methods
    # ------------------------------------------------------------------

    def __repr__(self) -> str:
        if not self._rows:
            return "Table(empty)"
        # Show first few rows for readability
        head = self._rows[:5]
        lines = [f"Table with {len(self._rows)} rows:"]
        for row in head:
            lines.append(f"  {row}")
        if len(self._rows) > 5:
            lines.append(f"  ... and {len(self._rows)-5} more")
        return "\n".join(lines)

    def __len__(self) -> int:
        return len(self._rows)

    def to_list(self) -> List[Dict[str, Any]]:
        """Return a deep copy of the internal row list."""
        return copy.deepcopy(self._rows)

