import re
from abc import ABC, abstractmethod
from typing import List, Optional, Tuple, Union


class ParseError(Exception):
    """Raised when an expression is malformed."""

    def __init__(self, message: str, pos: int) -> None:
        self.pos = pos
        super().__init__(f"position {pos}: {message}")


# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

class TokenType:
    NUMBER = "NUMBER"
    PLUS = "PLUS"
    MINUS = "MINUS"
    TIMES = "TIMES"
    DIVIDE = "DIVIDE"
    POW = "POW"
    LPAREN = "LPAREN"
    RPAREN = "RPAREN"
    EOF = "EOF"


Token = Tuple[str, Union[float, str]]


def tokenize(expression: str) -> List[Token]:
    tokens: List[Token] = []
    pos = 0
    length = len(expression)

    while pos < length:
        ch = expression[pos]

        # skip whitespace
        if ch.isspace():
            pos += 1
            continue

        if ch.isdigit() or (ch == '.' and pos + 1 < length and expression[pos + 1].isdigit()):
            # number: integer or float
            start = pos
            while pos < length and (expression[pos].isdigit() or expression[pos] == '.'):
                pos += 1
            num_str = expression[start:pos]
            if num_str.count('.') > 1:
                raise ParseError(f"invalid number literal {num_str!r}", start)
            tokens.append((TokenType.NUMBER, float(num_str)))
            continue

        if ch == '+':
            tokens.append((TokenType.PLUS, '+'))
            pos += 1
        elif ch == '-':
            tokens.append((TokenType.MINUS, '-'))
            pos += 1
        elif ch == '*':
            if pos + 1 < length and expression[pos + 1] == '*':
                tokens.append((TokenType.POW, '**'))
                pos += 2
            else:
                tokens.append((TokenType.TIMES, '*'))
                pos += 1
        elif ch == '/':
            tokens.append((TokenType.DIVIDE, '/'))
            pos += 1
        elif ch == '(':
            tokens.append((TokenType.LPAREN, '('))
            pos += 1
        elif ch == ')':
            tokens.append((TokenType.RPAREN, ')'))
            pos += 1
        else:
            raise ParseError(f"unexpected character {ch!r}", pos)

    tokens.append((TokenType.EOF, ''))
    return tokens


# ---------------------------------------------------------------------------
# AST nodes
# ---------------------------------------------------------------------------

class Expr(ABC):
    @abstractmethod
    def evaluate(self) -> float:
        ...


class Number(Expr):
    def __init__(self, value: float) -> None:
        self.value = value

    def evaluate(self) -> float:
        return self.value


class BinOp(Expr):
    def __init__(self, left: Expr, op: str, right: Expr) -> None:
        self.left = left
        self.op = op
        self.right = right

    def evaluate(self) -> float:
        left_val = self.left.evaluate()
        right_val = self.right.evaluate()
        if self.op == '+':
            return left_val + right_val
        elif self.op == '-':
            return left_val - right_val
        elif self.op == '*':
            return left_val * right_val
        elif self.op == '/':
            if right_val == 0.0:
                raise ZeroDivisionError("division by zero")
            return left_val / right_val
        elif self.op == '**':
            return left_val ** right_val
        else:
            raise ValueError(f"unknown operator {self.op!r}")


class UnaryOp(Expr):
    def __init__(self, op: str, operand: Expr) -> None:
        self.op = op
        self.operand = operand

    def evaluate(self) -> float:
        val = self.operand.evaluate()
        if self.op == '+':
            return val
        elif self.op == '-':
            return -val
        else:
            raise ValueError(f"unknown unary operator {self.op!r}")


# ---------------------------------------------------------------------------
# Parser (recursive descent)
# ---------------------------------------------------------------------------

class Parser:
    def __init__(self, tokens: List[Token]) -> None:
        self.tokens = tokens
        self.pos = 0

    def _current(self) -> Token:
        return self.tokens[self.pos]

    def _eat(self, expected_type: str) -> Tuple[str, Union[float, str]]:
        tok = self._current()
        if tok[0] != expected_type:
            self._error(f"expected {expected_type}, got {tok[0]}")
        self.pos += 1
        return tok

    def _error(self, message: str) -> None:
        # compute user-friendly position
        # tokens include the original char positions approximately;
        # we use the token index to estimate
        raise ParseError(message, self.pos)

    def parse(self) -> Expr:
        ast = self._expr()
        if self._current()[0] != TokenType.EOF:
            self._error("unexpected token after expression")
        return ast

    # expr   -> term ((PLUS|MINUS) term)*
    def _expr(self) -> Expr:
        left = self._term()
        while self._current()[0] in (TokenType.PLUS, TokenType.MINUS):
            op = self._eat(self._current()[0])[1]
            right = self._term()
            left = BinOp(left, op, right)
        return left

    # term   -> unary ((TIMES|DIVIDE) unary)*
    def _term(self) -> Expr:
        left = self._unary()
        while self._current()[0] in (TokenType.TIMES, TokenType.DIVIDE):
            op = self._eat(self._current()[0])[1]
            right = self._unary()
            left = BinOp(left, op, right)
        return left

    # unary  -> (PLUS|MINUS)* exponent
    def _unary(self) -> Expr:
        if self._current()[0] in (TokenType.PLUS, TokenType.MINUS):
            op = self._eat(self._current()[0])[1]
            operand = self._unary()
            return UnaryOp(op, operand)
        return self._exponent()

    # exponent -> atom (POW exponent)?   (right-associative)
    def _exponent(self) -> Expr:
        left = self._atom()
        if self._current()[0] == TokenType.POW:
            self._eat(TokenType.POW)
            right = self._exponent()   # right-associative -> recurse
            left = BinOp(left, '**', right)
        return left

    # atom   -> NUMBER | LPAREN expr RPAREN
    def _atom(self) -> Expr:
        tok = self._current()
        if tok[0] == TokenType.NUMBER:
            self._eat(TokenType.NUMBER)
            return Number(tok[1])  # type: ignore[arg-type]
        elif tok[0] == TokenType.LPAREN:
            self._eat(TokenType.LPAREN)
            expr = self._expr()
            self._eat(TokenType.RPAREN)
            return expr
        else:
            self._error(f"expected number or '('")


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def evaluate(expression: str) -> float:
    """Evaluate an arithmetic expression and return the result.

    Supports integers and floats, operators +, -, *, /, ** (right-associative),
    unary minus, and parentheses. Precedence from highest to lowest:
    ** → unary +/‑ → */ → +/‑.

    Raises ParseError on malformed input.
    """
    tokens = tokenize(expression)
    parser = Parser(tokens)
    ast = parser.parse()
    return ast.evaluate()


# ---------------------------------------------------------------------------
# Usage examples (run with `python -m <module>`)
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    examples = [
        ("2 + 3 * 4", 14.0),
        ("(2 + 3) * 4", 20.0),
        ("-3**2", -9.0),             # ** binds tighter than unary minus
        ("--5", 5.0),                # double unary minus
        ("2.5 * 4 + 1.5", 11.5),
        ("10 / (5 - 3)", 5.0),
        ("2 ** 3 ** 2", 512.0),      # right-associative: 2**(3**2) = 512
        ("-2 ** 3", -8.0),           # -(2**3) = -8
    ]

    print("Running examples...\n")
    all_ok = True
    for expr, expected in examples:
        try:
            result = evaluate(expr)
            ok = abs(result - expected) < 1e-12
            status = "✓" if ok else "✗"
            print(f"  {expr:20s} = {result:8g}  (expected {expected:8g})  {status}")
            if not ok:
                all_ok = False
        except Exception as e:
            print(f"  {expr:20s} = ERROR: {e}  ✗")
            all_ok = False

    # Also test error handling
    print("\nError handling examples:")
    bad_exprs = [
        "1 +",
        "(2 + 3",
        "2 **",
        "abc",
        "1 / 0",   # division by zero at runtime
    ]
    for expr in bad_exprs:
        try:
            evaluate(expr)
            print(f"  {expr:20s} = (unexpected success)  ✗")
            all_ok = False
        except (ParseError, ZeroDivisionError) as e:
            print(f"  {expr:20s} -> {e}  ✓")

    print(f"\nOverall: {'All passed' if all_ok else 'Some failed'}.")

from __future__ import annotations
from typing import Any, Callable, Dict, List

class Table:
    """An in-memory table holding a list of dict rows.
    Provides a fluent query API: methods return a new Table.
    """

    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        self._rows = rows

    # ---------- Query methods ----------

    def select(self, *columns: str) -> Table:
        """Return a new table containing only the specified columns."""
        return Table([{col: row[col] for col in columns} for row in self._rows])

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Table:
        """Return a new table with rows that satisfy *predicate*."""
        return Table([row for row in self._rows if predicate(row)])

    def join(
        self,
        other: Table,
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool],
    ) -> Table:
        """Inner join on a condition.
        Merges rows from both tables when *on(left, right)* is true.
        Raises ValueError if there are duplicate keys in the merged row.
        """
        result: List[Dict[str, Any]] = []
        for left in self._rows:
            for right in other._rows:
                if on(left, right):
                    merged = {**left, **right}
                    if len(merged) != len(left) + len(right):
                        raise ValueError(
                            "Duplicate keys found in join – keys from both sides must be disjoint"
                        )
                    result.append(merged)
        return Table(result)

    def group_by(self, column: str) -> Table:
        """Group rows by *column*. Returns a table where each row contains
        the group value and a ``'rows'`` key with the list of rows in that group.
        """
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self._rows:
            key = row[column]
            if key not in groups:
                groups[key] = []
            groups[key].append(row)
        return Table([{column: k, "rows": v} for k, v in groups.items()])

    def order_by(self, column: str, descending: bool = False) -> Table:
        """Return a new table sorted by *column* (ascending by default)."""
        return Table(
            sorted(self._rows, key=lambda r: r[column], reverse=descending)
        )

    def limit(self, n: int) -> Table:
        """Return a new table with at most *n* rows (first rows, no skip)."""
        return Table(self._rows[:n])

    # ---------- Utilities ----------

    def __repr__(self) -> str:
        return f"Table({self._rows!r})"

    def __len__(self) -> int:
        return len(self._rows)


# ========== Usage examples ==========

if __name__ == "__main__":
