from __future__ import annotations

import copy
from typing import Any, Callable, Dict, List, Optional


class Table:
    """An immutable, in‑memory table of rows (list of dicts)."""

    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        self._rows: List[Dict[str, Any]] = list(rows)  # defensive copy

    # ---------- Core query operators ----------

    def select(self, *columns: str) -> Table:
        """Projection – keep only *columns in each row."""
        for col in columns:
            if not any(col in row for row in self._rows):
                raise KeyError(f"Column '{col}' not found in any row")
        return Table(
            [{col: row[col] for col in columns} for row in self._rows]
        )

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Table:
        """Filter rows by predicate."""
        return Table([row for row in self._rows if predicate(row)])

    def join(
        self,
        other: Table,
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool],
    ) -> Table:
        """Inner join with *other* table.

        Combines rows by merging dicts (right‑side keys overwrite left‑side
        keys on conflict).
        """
        result: List[Dict[str, Any]] = []
        for left_row in self._rows:
            for right_row in other._rows:
                if on(left_row, right_row):
                    merged = {**left_row, **right_row}
                    result.append(merged)
        return Table(result)

    def group_by(self, column: str) -> Table:
        """Group rows by *column*.

        Returns a new table where each row contains the group key under
        *column* and a key ``"_rows"`` holding the list of stacked rows.
        """
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self._rows:
            key = row[column]
            groups.setdefault(key, []).append(row)

        result_rows = [
            {column: key, "_rows": rows} for key, rows in groups.items()
        ]
        return Table(result_rows)

    def order_by(
        self, column: str, *, descending: bool = False
    ) -> Table:
        """Sort rows by *column* (stable)."""
        if not self._rows:
            return Table([])
        if column not in self._rows[0]:
            raise KeyError(f"Column '{column}' not found in first row")
        return Table(
            sorted(
                self._rows,
                key=lambda r: r[column],
                reverse=descending,
            )
        )

    def limit(self, n: int) -> Table:
        """Keep only the first *n* rows."""
        return Table(self._rows[:n])

    # ---------- Utility ----------

    def __repr__(self) -> str:
        return f"Table({self._rows!r})"

    def __len__(self) -> int:
        return len(self._rows)

