from typing import List, Dict, Any, Callable, Optional

# Type alias for a single row
Row = Dict[str, Any]

class Table:
    """
    An in-memory table representation with a fluent query API.
    """
    def __init__(self, name: str, rows: List[Row]):
        self.name = name
        # Create a shallow copy to ensure immutability in the chain
        self._rows: List[Row] = list(rows)

    def select(self, *columns: str) -> 'Table':
        """
        Selects specific columns. If no columns are provided, returns all.
        """
        if not columns:
            return Table(self.name, self._rows)

        new_rows = []
        for row in self._rows:
            # Create a new dict with only the requested columns
            # We use a dict comprehension for efficiency
            selected = {col: row[col] for col in columns if col in row}
            new_rows.append(selected)

        return Table(self.name, new_rows)

    def where(self, predicate: Callable[[Row], bool]) -> 'Table':
        """
        Filters rows based on a predicate function.
        """
        filtered_rows = [row for row in self._rows if predicate(row)]
        return Table(self.name, filtered_rows)

    def join(self, other: 'Table', on: Callable[[Row, Row], bool]) -> 'Table':
        """
        Performs an inner join with another table.
        """
        joined_rows = []
        for left_row in self._rows:
            for right_row in other._rows:
                if on(left_row, right_row):
                    # Merge dictionaries. In case of key collision, right (other) wins.
                    merged = {**left_row, **right_row}
                    joined_rows.append(merged)

        return Table(f"{self.name}_joined", joined_rows)

    def group_by(self, column: str) -> 'Table':
        """
        Groups rows by a specific column.
        Note: Without aggregation functions, this behaves like SELECT DISTINCT 
        for the given column, returning unique values.
        """
        seen_values = set()
        distinct_rows = []

        for row in self._rows:
            if column in row:
                val = row[column]
                if val not in seen_values:
                    seen_values.add(val)
                    distinct_rows.append({column: val})

        return Table(self.name, distinct_rows)

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        """
        Orders the table by a specific column.
        """
        sorted_rows = sorted(
            self._rows, 
            key=lambda r: r.get(column, 0), # Handle missing keys gracefully
            reverse=descending
        )
        return Table(self.name, sorted_rows)

    def limit(self, n: int) -> 'Table':
        """
        Limits the number of rows.
        """
        return Table(self.name, self._rows[:n])

    def to_list(self) -> List[Row]:
        """Helper to retrieve the final list of rows."""
        return self._rows

    def __repr__(self) -> str:
        return f"<Table {self.name} ({len(self._rows)} rows)>"

