@dataclass(frozen=True)
class Table:
    """In-memory table holding rows as dictionaries.

    Supports fluent composable operations: where, select, join,
    group_by, order_by, limit.
    """

    _data: List[Row]
    _name: str = "anonymous"

    def __post_init__(self) -> None:
        # Ensure immutable: store a copy
        object.__setattr__(self, '_data', list(self._data))

    @classmethod
    def from_rows(cls, rows: List[Row], name: str = "table") -> "Table":
        """Create Table from list of row dictionaries."""
        return cls(_data=list(rows), _name=name)

    @property
    def rows(self) -> List[Row]:
        """Access the underlying row data."""
        return list(self._data)

    @property
    def name(self) -> str:
        """Table name for debugging."""
        return self._name

    def where(self, predicate: Predicate) -> "Table":
        """Filter rows by predicate function.

        Args:
            predicate: Function that returns True for rows to keep.

        Returns:
            New Table with filtered rows.
        """
        filtered = [row for row in self._data if predicate(row)]
        return Table(_data=filtered, _name=self._name)

    def select(self, *columns: str) -> "Table":
        """Project to specific columns.

        Args:
            *columns: Column names to keep.

        Returns:
            New Table with only the specified columns.
        """
        selected = [
            {col: row[col] for col in columns if col in row}
            for row in self._data
        ]
        return Table(_data=selected, _name=self._name)

    def join(
        self,
        other: "Table",
        on: JoinCondition,
        how: str = "inner"
    ) -> "Table":
        """Join with another table.

        Args:
            other: Table to join with.
            on: Predicate taking (left_row, right_row) returning True for matches.
            how: Join type - "inner", "left", "right", "outer". Defaults to "inner".

        Returns:
            New Table with joined rows (columns from both tables merged).
        """
        other_data = {id(r): r for r in other._data}

        joined: List[Row] = []
        matched_right: set[int] = set()

        for left_row in self._data:
            for right_row in other._data:
                if on(left_row, right_row):
                    merged = {**right_row, **left_row}
                    joined.append(merged)
                    matched_right.add(id(right_row))

        if how == "left":
            for right_row in other._data:
                if id(right_row) not in matched_right:
                    joined.append({**right_row})

        if how == "right":
            for left_row in self._data:
                has_match = False
                for right_row in other._data:
                    if on(left_row, right_row):
                        has_match = True
                        break
                if not has_match:
                    joined.append({**left_row})

        if how == "outer":
            for right_row in other._data:
                if id(right_row) not in matched_right:
                    joined.append({**right_row})

        return Table(_data=joined, _name=f"{self._name}_join_{other._name}")

    def group_by(self, column: str) -> Dict[Any, "Table"]:
        """Group rows by column value.

        Args:
            column: Column name to group by.

        Returns:
            Dict mapping column value to Table of matching rows.
        """
        groups: Dict[Any, List[Row]] = {}
        for row in self._data:
            key = row.get(column)
            if key not in groups:
                groups[key] = []
            groups[key].append(row)

        return {
            key: Table(_data=rows, _name=f"{self._name}_group_{key}")
            for key, rows in groups.items()
        }

    def order_by(self, column: str, descending: bool = False) -> "Table":
        """Sort rows by column.

        Args:
            column: Column name to sort by.
            descending: If True, sort in descending order.

        Returns:
            New Table with sorted rows.
        """
        sorted_data = sorted(
            self._data,
            key=lambda row: row.get(column),
            reverse=descending
        )
        return Table(_data=sorted_data, _name=self._name)

    def limit(self, n: int) -> "Table":
        """Limit number of rows.

        Args:
            n: Maximum number of rows to return.

        Returns:
            New Table with at most n rows.
        """
        return Table(_data=self._data[:n], _name=self._name)

    def aggregate(self, column: str, agg: str) -> Any:
        """Simple aggregation on a column.

        Args:
            column: Column to aggregate.
            agg: Aggregation type - "sum", "avg", "min", "max", "count".

        Returns:
            Aggregated value.
        """
        values = [row.get(column) for row in self._data if column in row]

        if not values:
            return None

        if agg == "count":
            return len(values)
        if agg == "sum":
            return sum(values)
        if agg == "avg":
            return sum(values) / len(values)
        if agg == "min":
            return min(values)
        if agg == "max":
            return max(values)

        raise ValueError(f"Unknown aggregation: {agg}")

    def count(self) -> int:
        """Return number of rows."""
        return len(self._data)

    def __iter__(self) -> Iterator[Row]:
        """Iterate over rows."""
        return iter(self._data)

    def __len__(self) -> int:
        """Return row count."""
        return len(self._data)

    def __repr__(self) -> str:
        return f"Table(name={self._name!r}, rows={len(self._data)})"


