    for row in top_earners:
        print(f"  {row['name']}: ${row['salary']:,}")

"""In-memory SQL-like query engine with a fluent, composable API."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Callable, TypeVar, Generic

T = TypeVar("T")


@dataclass
class Table:
    """In-memory table holding a list of dictionary rows.

    Provides a fluent, composable API for querying and transforming data
    in a SQL-like manner without requiring a database.
    """

    _rows: list[dict[str, Any]] = field(default_factory=list)
    _name: str = ""

    def __init__(self, rows: list[dict[str, Any]] | None = None, name: str = "") -> None:
        self._rows = list(rows) if rows else []
        self._name = name

    @property
    def rows(self) -> list[dict[str, Any]]:
        """Return a copy of rows to prevent external mutation."""
        return list(self._rows)

    @property
    def columns(self) -> list[str]:
        """Return all unique column names in the table."""
        if not self._rows:
            return []
        return list(set().union(*(row.keys() for row in self._rows)))

    def __iter__(self):
        """Allow iteration over rows."""
        return iter(self._rows)

    def __len__(self) -> int:
        return len(self._rows)

    def __repr__(self) -> str:
        return f"Table(rows={len(self._rows)}, columns={self.columns})"

    def select(self, *columns: str) -> Table:
        """Select specific columns from the table.

        Args:
            *columns: Column names to include. If empty, returns all columns.

        Returns:
            New Table with only the specified columns.
        """
        if not columns:
            return Table(list(self._rows), name=self._name)

        return Table(
            [{col: row.get(col) for col in columns} for row in self._rows],
            name=self._name
        )

    def where(self, predicate: Callable[[dict[str, Any]], bool]) -> Table:
        """Filter rows using a predicate function.

        Args:
            predicate: Function that takes a row dict and returns bool.

        Returns:
            New Table containing only rows where predicate returns True.
        """
        return Table([row for row in self._rows if predicate(row)], name=self._name)

    def join(
        self,
        other: Table,
        on: Callable[[dict[str, Any], dict[str, Any]], bool],
        how: str = "inner"
    ) -> Table:
        """Join with another table.

        Args:
            other: Table to join with.
            on: Predicate function taking (left_row, right_row) -> bool.
            how: Join type - "inner", "left", "right". Defaults to "inner".

        Returns:
            New Table with merged rows.
        """
        results: list[dict[str, Any]] = []

        if how == "inner":
            for left in self._rows:
                for right in other._rows:
                    if on(left, right):
                        results.append({**left, **right})

        elif how == "left":
            matched = set()
            for i, left in enumerate(self._rows):
                found = False
                for j, right in enumerate(other._rows):
                    if on(left, right):
                        results.append({**left, **right})
                        matched.add(j)
                        found = True
                if not found:
                    results.append({**left})

        elif how == "right":
            matched = set()
            for i, right in enumerate(other._rows):
                found = False
                for j, left in enumerate(self._rows):
                    if on(left, right):
                        results.append({**left, **right})
                        matched.add(j)
                        found = True
                if not found:
                    results.append({**right})

        return Table(results)

    def group_by(self, column: str) -> GroupedTable:
        """Group rows by a column value.

        Args:
            column: Column name to group by.

        Returns:
            GroupedTable with groups accessible by key.
        """
        groups: dict[Any, list[dict[str, Any]]] = {}
        for row in self._rows:
            key = row.get(column)
            if key not in groups:
                groups[key] = []
            groups[key].append(row)

        return GroupedTable(groups, column)

    def order_by(self, column: str, descending: bool = False) -> Table:
        """Order rows by a column.

        Args:
            column: Column name to sort by.
            descending: If True, sort in descending order.

        Returns:
            New Table with rows sorted.
        """
        return Table(
            sorted(self._rows, key=lambda r: r.get(column), reverse=descending),
            name=self._name
        )

    def limit(self, n: int) -> Table:
        """Limit the number of rows.

        Args:
            n: Maximum number of rows to return.

        Returns:
            New Table with at most n rows.
        """
        return Table(self._rows[:n], name=self._name)

    def to_list(self) -> list[dict[str, Any]]:
        """Convert table to list of dictionaries."""
        return list(self._rows)


@dataclass
class GroupedTable:
    """Result of a group_by operation.

    Provides access to grouped data and basic aggregation.
    """

    _groups: dict[Any, list[dict[str, Any]]]
    _group_column: str

    def __getitem__(self, key: Any) -> Table:
        """Get table for a specific group key."""
        return Table(self._groups.get(key, []))

    def keys(self) -> Any:
        """Return group keys."""
        return self._groups.keys()

    def items(self) -> list[tuple[Any, Table]]:
        """Return (key, table) pairs."""
        return [(k, Table(v)) for k, v in self._groups.items()]

    def count(self) -> dict[Any, int]:
        """Return count per group."""
        return {k: len(v) for k, v in self._groups.items()}

    def sum(self, column: str) -> dict[Any, float]:
        """Return sum of a column per group."""
        result = {}
        for k, rows in self._groups.items():
            total = sum(row.get(column, 0) for row in rows)
            result[k] = total
        return result

    def avg(self, column: str) -> dict[Any, float]:
        """Return average of a column per group."""
        result = {}
        for k, rows in self._groups.items():
            values = [row.get(column, 0) for row in rows if column in row]
            result[k] = sum(values) / len(values) if values else 0
        return result


