    employees = Table([
        {"id": 1, "name": "Alice", "dept": "Engineering", "salary": 85000},
        {"id": 2, "name": "Bob", "dept": "Engineering", "salary": 92000},
        {"id": 3, "name": "Carol", "dept": "Sales", "salary": 78000},
