    ])

    # Find engineering employees earning > 80k, select name and salary, order by salary desc
    result = (
        employees
        .where(lambda r: r["dept"] == "Engineering" and r["salary"] > 80000)
        .select("name", "salary")
        .order_by("salary", descending=True)
    )

    print("Engineering employees earning > $80k (by salary desc):")
    for row in result:
        print(f"  {row['name']}: ${row['salary']:,}")

