    print("\n" + "=" * 60)
    print("Example 2: Joining tables")
    print("=" * 60)

    users = Table([
        {"user_id": 1, "username": "alice", "city_id": 101},
        {"user_id": 2, "username": "bob", "city_id": 102},
        {"user_id": 3, "username": "charlie", "city_id": 101},
    ])

    cities = Table([
        {"city_id": 101, "city_name": "New York", "country": "USA"},
        {"city_id": 102, "city_name": "London", "country": "UK"},
        {"city_id": 103, "city_name": "Paris", "country": "France"},
    ])

    # Join users with cities on city_id
    user_cities = users.join(cities, on=lambda u, c: u["city_id"] == c["city_id"])

    print("Users with their cities:")
    for row in user_cities.select("username", "city_name", "country"):
        print(f"  {row['username']} -> {row['city_name']}, {row['country']}")

    # Example 3: Grouping and aggregation
    print("\n" + "=" * 60)
    print("Example 3: Grouping and aggregation")
    print("=" * 60)

    sales = Table([
        {"product": "Widget", "region": "North", "amount": 150},
        {"product": "Widget", "region": "South", "amount": 200},
        {"product": "Gadget", "region": "North", "amount": 300},
        {"product": "Gadget", "region": "South", "amount": 250},
        {"product": "Widget", "region": "North", "amount": 175},
    ])

    # Group by product and calculate totals
    by_product = sales.group_by("product")

    print("Sales by product:")
    for product, table in by_product.items():
        total = sum(row["amount"] for row in table)
        print(f"  {product}: ${total}")

    # Group by region with average
    by_region = sales.group_by("region")

    print("\nAverage sale amount by region:")
    for region, table in by_region.items():
        avg = sum(row["amount"] for row in table) / len(table)
        print(f"  {region}: ${avg:.2f}")

